mapper.sql:
WHERE d.BILLDATE = #{q.billdate}
  AND d.AD_PI_ID IS NULL

    AND d.C_STORE_ID = #{q.storeId}


    AND mp.NAME LIKE '%' || #{q.productCode} || '%'


    AND mp.GOODSNAME LIKE '%' || #{q.productName} || '%'

mapper.select:
SELECT NVL(SUM(ms.qtyend), 0)
FROM ods_fa_monthstore ms
WHERE ms.c_period_id = #{cPeriodId}
  AND ms.yearmonth   = #{yearmonth}
  AND ms.c_store_id     = #{q.storeId}
  AND ms.m_product_id   = #{q.productId}
  AND NVL(ms.m_attributesetinstance_id, -1) = NVL(#{q.attrInstanceId}, -1)

SELECT f.changedate  AS "changedate",
       f.docno       AS "docno",
       f.doctype     AS "doctype",
       f.billtype    AS "billtype",
       f.qtychange   AS "qtychange"
FROM ods_fa_storage_ftp f
WHERE f.c_store_id   = #{q.storeId}
  AND f.m_product_id = #{q.productId}
  AND NVL(f.m_attributesetinstance_id, -1) = NVL(#{q.attrInstanceId}, -1)
  AND f.qtychange <> 0
  AND f.changedate > #{periodDateend}
  AND f.changedate <= #{q.billdate}
ORDER BY f.changedate, f.docno
